local CommonTipsCountDown = import("Game.UI.Common.CommonTipsCountdown")
--endregion import

local RE_USE_TYPE = {
    DREAM_ADVENTURE = 1,
    MINI_WORLD = 2,
}

---@class DreamAdventuresStaminaTipsCountDown
local DreamAdventuresStaminaTipsCountDown = Class('DreamAdventuresStaminaTipsCountDown', CommonTipsCountDown)

--region lifecycle

function DreamAdventuresStaminaTipsCountDown:__init()
    CommonTipsCountDown.__init(self)
    self.type = RE_USE_TYPE.DREAM_ADVENTURE
    self.events = {}
end

function DreamAdventuresStaminaTipsCountDown:__delete()
    CommonTipsCountDown.__delete(self)
    self.events = nil
end

function DreamAdventuresStaminaTipsCountDown:SetTimerType(type)
    self.type = checkNumber(type)
end

function DreamAdventuresStaminaTipsCountDown:Awake()
    CommonTipsCountDown.Awake(self)
    self._countDownFuncPtr = self.RefreshCountdownForDreamAdventures
    CfUtils.FillText(self.TextHPNext_Time, CfUtils.GetTimeHMS(0))
    CfUtils.FillText(self.TextHPWhole_Time, localize("恢复已满"))
    self:InitHandler()
end

function DreamAdventuresStaminaTipsCountDown:Start()
    CommonTipsCountDown.Start(self)
end

function DreamAdventuresStaminaTipsCountDown:OnDestroy()
    for k, v in pairs(self.events) do
        Events.RemoveListener(k, v)
    end

    CommonTipsCountDown.OnDestroy(self)
end
--endregion lifecycle

--region public
function DreamAdventuresStaminaTipsCountDown:RefreshCountdownForDreamAdventures(goodsId)
    if isNull(self.playerDojo) then return end
    self.TextHPDesc.text = self:GetGoodRecoverDesc(self.goodsId)
    self:SetItemNum(self.goodsId)
end
--endregion public

--region private
function DreamAdventuresStaminaTipsCountDown:InitHandler()
    self.events[Constants.EventNames.DreamAdventuresActivityHpChange] = Events.AddListener(Constants.EventNames.DreamAdventuresActivityHpChange, Bind(self, self.CountDownListener))
    self.events["MINI_WORLD_COUNT_DOWN"] = Events.AddListener("MINI_WORLD_COUNT_DOWN", Bind(self, self.CountDownListener))
    self.events[Constants.EventNames.EveryThingChangeEventName] = Events.AddListener(Constants.EventNames.EveryThingChangeEventName, Bind(self, self.GoodsChangeHandler))
end

function DreamAdventuresStaminaTipsCountDown:CountDownListener(isFull, cdTime, totalCDTime)
    if checkBool(isFull) then
        CfUtils.FillText(self.TextHPNext_Time, CfUtils.GetTimeHMS(0))
        CfUtils.FillText(self.TextHPWhole_Time, localize("恢复已满"))
        return
    end
    CfUtils.FillText(self.TextHPNext_Time, CfUtils.GetTimeHMS(cdTime))
    CfUtils.FillText(self.TextHPWhole_Time, CfUtils.GetTimeHMS(totalCDTime))
end

function DreamAdventuresStaminaTipsCountDown:GoodsChangeHandler()
    if self.type == RE_USE_TYPE.DREAM_ADVENTURE then
        local dreamAdventuresMgr = import("Game.Activity.DreamAdventures.DreamAdventuresMgr"):GetInstance()
        self:SetItemNum(dreamAdventuresMgr:GetActivityHPId())
    else
        ---@type ParkourGameMgr
        local ParkourGameMgr = import("Game.Activity.ParkourGame.ParkourGameMgr"):GetInstance()
        self:SetItemNum(ParkourGameMgr:GetActivityHPId())
    end
end
